static void app_lvgldemo_log(int priority, const char *fmt, ...)
{
  va_list ap;
  va_list syslog_ap;

  printf("[%s] ", APP_LVGLDEMO_TAG);

  va_start(ap, fmt);
  va_copy(syslog_ap, ap);
  vprintf(fmt, ap);
  printf("\n");
  fflush(stdout);
  va_end(ap);

  vsyslog(priority, fmt, syslog_ap);
  va_end(syslog_ap);
}

