    {
      syslog(LOG_ERR, "app_lvgldemo autostart attr init failed: %d\n", ret);
      posix_spawn_file_actions_destroy(&actions);
      return ret;
    }

  posix_spawnattr_setpriority(&attr, CONFIG_APP_LOCAL_LVGLDEMO_PRIORITY);
  posix_spawnattr_setstacksize(&attr, CONFIG_APP_LOCAL_LVGLDEMO_STACKSIZE);

