static bool app_lvgldemo_wait_device(const char *path, uint32_t timeout_ms)
{
  uint32_t waited_ms = 0;

  if (path == NULL || path[0] == '\0')
    {
      return false;
    }

  while (access(path, F_OK) < 0)
    {
      if (waited_ms >= timeout_ms)
        {
          app_lvgldemo_log(LOG_WARNING,
                           "display device %s not found after %u ms: errno=%d",
                           path, (unsigned int)waited_ms, errno);
          return false;
        }

      usleep(50 * 1000);
      waited_ms += 50;
    }

  app_lvgldemo_log(LOG_INFO, "display device ready: %s wait=%u ms",
                   path, (unsigned int)waited_ms);
  return true;
}

